        Query::put($query, 'locale', $lang);

        return $this->http->requestArray('/v1/panchang/varjyam', $query, $requestOptions);
    }

    /**
     * Yamaganda inauspicious window.
     *
     * Cost: 10 credits per call.
     *
     * `GET /v1/panchang/yamaganda`
     *
     * @param float $lat Latitude in decimal degrees.
